                               {/* Label (Optional: uncomment to show label) */}
                               {/* <span className={`text-[10px] font-bold mt-1 transition-all duration-300 ${isActive ? 'text-gray-900 opacity-100' : 'text-gray-400 opacity-0 h-0 overflow-hidden'}`}>{label}</span> */}
                           </button>
                       );
