    setIsProcessingOrder(true);

    const total = cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const orderId = `ORD-${Math.floor(Math.random() * 10000)}`;
    const newOrder: OrderHistoryItem = {
