                                        <div className="flex justify-between items-end">
                                            {ann.priceTag && (
                                                <span className="bg-brand-yellow text-brand-dark px-4 py-1.5 rounded-full font-bold shadow-lg text-sm">
                                                    {ann.priceTag}
