import { GoogleGenAI } from "@google/genai";
import { Category } from "../types";

export const getCoffeeRecommendation = async (userQuery: string, menuData: Category[]): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Please provide an API Key to use the Coffee Concierge.";
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-flash-preview";

  // Flatten menu for context
  const menuContext = menuData.map(cat => 
    `${cat.name}: ${cat.items.map(item => `${item.name} ($${item.price})`).join(', ')}`
  ).join('\n');

  const systemInstruction = `You are a helpful barista assistant at KAINOR Coffee & Food. 
  Your goal is to recommend drinks or pastries from our menu based on the user's preference.

  Here is our Live Menu:
  ${menuContext}

  Keep your answers short, friendly, and enthusiastic. Always mention the price of the recommended item.
  If the user asks about something not on the menu, politely suggest a similar item we do have.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: userQuery,
      config: {
        systemInstruction: systemInstruction,
      }
    });

    return response.text || "I'm sorry, I couldn't think of a recommendation right now. Try checking our Best Sellers!";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm having a little trouble connecting to the recipe book (API Error). Please try again later.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageCircle, X, Send, Bot } from 'lucide-react';
import { getCoffeeRecommendation } from '../services/geminiService';
import { Category } from '../types';

interface GeminiAssistantProps {
  menuData: Category[];
}

export const GeminiAssistant: React.FC<GeminiAssistantProps> = ({ menuData }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'assistant', text: string }[]>([
    { role: 'assistant', text: "Hi! I'm your AI Barista. Unsure what to order? Tell me what you like!" }
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg = input;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput("");
    setLoading(true);

    // Pass the live menuData to the service
    const response = await getCoffeeRecommendation(userMsg, menuData);

    setMessages(prev => [...prev, { role: 'assistant', text: response }]);
    setLoading(false);
  };

  if (!isOpen) {
    return (
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-20 right-4 z-40 bg-brand-yellow text-brand-dark p-3 rounded-full shadow-lg hover:bg-yellow-300 transition-all transform hover:scale-105"
      >
        <Bot size={28} />
      </button>
    );
  }

  return (
    <div className="fixed bottom-24 right-4 z-50 w-80 md:w-96 bg-white rounded-2xl shadow-2xl flex flex-col overflow-hidden border border-gray-100 font-sans">
      <div className="bg-brand-yellow p-4 flex justify-between items-center text-brand-dark">
        <div className="flex items-center gap-2">
            <Bot size={20} />
            <h3 className="font-bold">AI Barista</h3>
        </div>
        <button onClick={() => setIsOpen(false)} className="hover:bg-white/20 p-1 rounded">
          <X size={20} />
        </button>
      </div>

      <div className="flex-1 h-80 overflow-y-auto p-4 bg-gray-50">
        {messages.map((msg, idx) => (
          <div key={idx} className={`mb-3 flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-3 rounded-xl text-sm ${
              msg.role === 'user' 
                ? 'bg-gray-800 text-white rounded-br-none' 
                : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'
            }`}>
              {msg.text}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start mb-3">
            <div className="bg-gray-100 p-3 rounded-xl rounded-bl-none text-gray-500 text-xs animate-pulse">
              Brewing response...
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-3 bg-white border-t flex gap-2">
        <input 
          type="text" 
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSend()}
          placeholder="I want something sweet..."
          className="flex-1 bg-gray-100 border-none rounded-full px-4 py-2 text-sm focus:ring-2 focus:ring-brand-yellow focus:outline-none"
        />
        <button 
          onClick={handleSend}
          disabled={loading}
          className="bg-brand-yellow text-brand-dark p-2 rounded-full hover:bg-yellow-300 disabled:opacity-50"
        >
          <Send size={18} />
        </button>
      </div>
    </div>
  );
};

