      <h3 className="text-lg font-bold text-gray-800 mb-4">Recent Sales</h3>
      <ResponsiveContainer width="100%" height="80%">
        <BarChart data={data} margin={{ top: 5, right: 20, left: -20, bottom: 0 }}>
          <XAxis 
            dataKey="date" 
