                                <span className={`text-[10px] uppercase font-bold px-2 py-1 rounded bg-gray-100 text-gray-500`}>{order.status}</span>
                                <button className="text-xs font-bold text-brand-yellow hover:underline">Reorder</button>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

const NavButton = ({ icon: Icon, label, isActive, onClick }: any) => (
    <button 
        onClick={onClick}
        className={`flex flex-col items-center gap-1 transition-all duration-300 ${isActive ? 'text-brand-yellow -translate-y-1' : 'text-gray-400 hover:text-gray-600'}`}
