const App = () => {
  const [activeTab, setActiveTab] = useState('home');
  const [activeCategory, setActiveCategory] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<OrderHistoryItem[]>(MOCK_HISTORY);
  const [menuData, setMenuData] = useState<Category[]>(MENU_DATA);
  const [announcements, setAnnouncements] = useState<Announcement[]>(INITIAL_ANNOUNCEMENTS);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);

  // Fetch data on mount
  const fetchData = async () => {
      // Fetch logic here, merging with mocks or replacing
      // For now, let's just stick to initial data or simple fetch if needed
      // But AdminDashboard has refreshData logic, we can reuse or share

      // Let's implement a simple fetch from supabase that falls back to constants if empty
      // ...
  };

  useEffect(() => {
    fetchData();
  }, []);

  const refreshData = async () => {
      // Implement data fetching for menu, announcements, orders
      // For menu, we need to restructure flat products into categories

      const { data: categories } = await supabase.from('categories').select('*');
      const { data: products } = await supabase.from('products').select('*');
      const { data: anns } = await supabase.from('announcements').select('*');
      const { data: orderData } = await supabase.from('orders').select('*').order('created_at', { ascending: false });

      if (categories && products) {
          const newMenu = categories.map((cat: any) => ({
              ...cat,
              id: cat.id,
              name: cat.name,
              iconName: cat.icon_name,
              items: products.filter((p: any) => p.category_id === cat.id).map((p: any) => ({
                  ...p,
                  price: Number(p.price) // Ensure number
              }))
          }));
          setMenuData(newMenu);
          // Set active category if not set
          if (!activeCategory && newMenu.length > 0) setActiveCategory(newMenu[0].id);
      }

      if (anns) {
          setAnnouncements(anns.map((a: any) => ({
              ...a,
              priceTag: a.price_tag,
              colorClass: a.color_class
          })));
      }

      if (orderData) {
          // map to OrderHistoryItem
           setOrders(orderData.map((o: any) => ({
               id: o.readable_id || o.id,
               date: o.created_at,
               total: o.total,
               items: o.items || [], // assume json array
               status: o.status,
               customerName: o.customer_name,
               tableNumber: o.table_number
           })));
      }
  };

  const addToCart = (product: Product, quantity: number, customization: any) => {
      const newItem: CartItem = { 
          ...product, 
          quantity, 
          customization, 
          cartId: Math.random().toString(36).substr(2, 9) 
      };
      setCart(prev => [...prev, newItem]);
      setSelectedProduct(null);
      setActiveTab('cart');
  };

  const removeFromCart = (cartId: string) => {
      setCart(prev => prev.filter(item => item.cartId !== cartId));
  };

  if (isAdmin) {
      return <AdminDashboard 
          menuData={menuData} 
          refreshData={refreshData} 
          orders={orders} 
          announcements={announcements}
          onLogout={() => setIsAdmin(false)} 
      />;
  }

  return (
    <div className="bg-gray-100 min-h-screen relative max-w-md mx-auto md:max-w-full md:flex md:justify-center">
        <div className="w-full md:max-w-md bg-white min-h-screen shadow-2xl relative overflow-hidden flex flex-col">

            {/* Main Content Area */}
            <div className="flex-1 overflow-y-auto no-scrollbar pb-24">
                {activeTab === 'home' && (
                    <HomeView onNavigateToMenu={() => { setActiveTab('menu'); }} announcements={announcements} />
                )}

                {activeTab === 'menu' && (
                    <MenuView 
                        activeCategory={activeCategory} 
                        setActiveCategory={setActiveCategory} 
                        onProductClick={setSelectedProduct}
                        menuData={menuData}
                    />
                )}

                {activeTab === 'cart' && (
                    <CartView cart={cart} onRemove={removeFromCart} />
                )}

                {activeTab === 'account' && (
                    <AccountView onAdminClick={() => setShowAdminLogin(true)} orders={orders} />
                )}
            </div>

            {/* Bottom Navigation */}
            <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-100 px-6 py-2 flex justify-between items-center z-40 md:absolute md:w-full">
                <NavButton icon={Home} label="Home" isActive={activeTab === 'home'} onClick={() => setActiveTab('home')} />
                <NavButton icon={Coffee} label="Menu" isActive={activeTab === 'menu'} onClick={() => setActiveTab('menu')} />
                <div className="relative">
                    <div className="absolute -top-3 -right-2 bg-brand-yellow text-brand-dark text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full shadow-sm animate-in zoom-in">
                        {cart.length}
                    </div>
                    <NavButton icon={ShoppingBag} label="Cart" isActive={activeTab === 'cart'} onClick={() => setActiveTab('cart')} />
                </div>
                <NavButton icon={User} label="Account" isActive={activeTab === 'account'} onClick={() => setActiveTab('account')} />
            </div>

            {/* Detail Modal */}
            {selectedProduct && (
                <ProductDetail 
                    product={selectedProduct} 
                    onBack={() => setSelectedProduct(null)} 
                    onAddToCart={addToCart} 
                />
            )}

            {/* Admin Login Modal */}
            {showAdminLogin && (
                <AdminLogin onLogin={() => { setIsAdmin(true); setShowAdminLogin(false); }} onCancel={() => setShowAdminLogin(false)} />
            )}

            {/* Gemini Assistant */}
            <GeminiAssistant menuData={menuData} />

        </div>
    </div>
  );
};

export default App;

