                                        {isUploading ? <Loader2 size={16} className="animate-spin" /> : <Upload size={16} />}
                                        <span>{isUploading ? 'Uploading...' : 'Upload from Device'}</span>
                                        <input type="file" id="ann-image-upload" className="hidden" accept="image/*" onChange={(e) => handleImageUpload(e, 'announcement')} disabled={isUploading} />
                                    </label>
