                                                {item}
                                            </p>
                                        ))}
                                    </div>
                                    <div className="flex justify-between items-center mt-3 pt-3 border-t border-gray-50">
                                        <span className="font-bold text-lg text-brand-yellow">${order.total.toFixed(2)}</span>
